import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy technical design","description":"Historical snapshot preserved November 11, 2026 before the technical-document cleanup.\\nUse the current document for the active design.","frontmatter":{"title":"Chainy technical design","description":"Historical snapshot preserved November 11, 2026 before the technical-document cleanup.\\nUse the current document for the active design.","source":"docs/archive/pre-lesson-collection-2026-11-11/technical-design.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/technical-design.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/technical-design.md"}'),s={name:"content/docs/archive/pre-lesson-collection-2026-11-11/technical-design.md"};function o(i,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n(`<div><blockquote><p>Historical snapshot preserved November 11, 2026 before the technical-document cleanup. Use the <a href="/Chainy-Docs/content/docs/technical-design.html">current document</a> for the active design.</p></blockquote><h1 id="chainy-technical-design">Chainy technical design<a class="header-anchor" href="#chainy-technical-design" aria-label="Link to this section">​</a></h1><p>Updated November 11, 2026 for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> and <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-baseline.html">current decisions</a>. <strong>Development gate: documentation and necessary preparation only until the owner&#39;s explicit FINAL approval.</strong> This document proposes responsibilities and contracts; it does not authorize Unity edits, scene changes, migrations, builds, or implementation agents.</p><h2 id="current-architecture">Current architecture<a class="header-anchor" href="#current-architecture" aria-label="Link to this section">​</a></h2><p>The game runs offline on one Android device, with three sequential worlds, 13 ordered lessons per world, and nine distinct minigame scenes. Lesson collection, encyclopedia entries, tutorial progress, minigame prerequisites, and required review completion share one authoritative progress owner. No economy, inventory-management service, or network backend is needed.</p><table><thead><tr><th>Responsibility</th><th>Proposed boundary</th><th>Existing capability to evaluate for reuse</th></tr></thead><tbody><tr><td>Presentation</td><td>Display world access, objectives, encyclopedia entries, feedback, and errors; send player intentions through handlers</td><td>Existing movement controls, dialogue, quest UI, and encyclopedia UI recorded in the November 11 audit</td></tr><tr><td>Journey progress</td><td>Validate profile, tutorial, exact next lesson, encounter step, and world access; publish read-only state after successful commits</td><td>Existing profile and lesson/quest helpers; their compatibility with the new contract is not established</td></tr><tr><td>Activity rules</td><td>Evaluate the concrete minigame win condition or authored quiz answer; report a typed result for the originating profile/world/lesson or attempt</td><td>Existing activity and Quiz patterns may supply infrastructure; Wordle completion is not evidence that the nine new activities exist</td></tr><tr><td>Scene lifecycle</td><td>Load one active mode, disable duplicate input, and return to the originating island&#39;s safe checkpoint</td><td>Existing scene/input infrastructure; exact scene wiring remains future implementation work</td></tr><tr><td>Persistence</td><td>Queue reads/writes through the existing <code>IDatabaseSystem</code>; commit related progress atomically</td><td>The audited <code>DatabaseBridge</code> owns a queued SQLite connection and offers <code>RunInTransactionAsync</code></td></tr><tr><td>Authored content</td><td>Provide stable lesson/activity/question IDs, order, examples, answers, and version</td><td>Existing ScriptableObject/content-loading patterns; select one authoritative packaged source during approved implementation</td></tr></tbody></table><p>Use View → Handler → Service for commands and typed events for notifications. Retain ServiceRegistry lifecycle conventions and existing module boundaries rather than creating another manager framework. Activity/UI code must not open another SQLite connection or directly mark a world complete. The proposed logical state and transactions are specified once in the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/database-schema.html#current-progress-contract">database contract</a>.</p><h2 id="proposed-command-and-result-contract">Proposed command and result contract<a class="header-anchor" href="#proposed-command-and-result-contract" aria-label="Link to this section">​</a></h2><p>Each command carries the expected profile and its relevant world, lesson, or quiz-attempt ID. Reject stale callbacks after a profile change and reject an activity result that does not belong to the current encounter. Serialize progress-changing commands and revalidate persisted state inside the transaction so repeated taps or overlapping saves cannot overwrite newer progress.</p><table><thead><tr><th>Command</th><th>Required behavior</th></tr></thead><tbody><tr><td>Load profile</td><td>Validate supported content/schema and load isolated progress before enabling play</td></tr><tr><td>Complete tutorial</td><td>Persist orientation for the selected unlocked world only</td></tr><tr><td>Advance encounter</td><td>Persist item/NPC prerequisites in order for the current minigame lesson; repeated completed steps are harmless</td></tr><tr><td>Record lesson</td><td>Validate collectible or minigame outcome, then commit lesson, encyclopedia entry, next objective, and encounter reset together</td></tr><tr><td>Start/answer/finish review</td><td>Track an identified attempt, first responses and corrections; Finish commits review completion and the next-world unlock only after all five fixed items are resolved</td></tr><tr><td>Abandon/replay review</td><td>Retain the attempt&#39;s partial evidence, start all five questions in a new attempt on return, and preserve any earlier world completion</td></tr></tbody></table><p>These are behavior contracts, not already implemented API names. The nine activities may share scene loading, pause, and storage code while retaining their distinct rules. An authored AI simulation must remain labeled as such; it does not require training or hosting a model.</p><h2 id="recovery-and-verification-boundary">Recovery and verification boundary<a class="header-anchor" href="#recovery-and-verification-boundary" aria-label="Link to this section">​</a></h2><p>Save prerequisite steps before scene entry; scene failure or minigame exit grants no lesson entry. Successful saving precedes the Recorded label, next quest, world completion, or next-world access. Save failure leaves the previous committed state usable and presents Retry; incompatible data is preserved for recovery rather than reset. Relaunch restores a supported checkpoint, not a partially played minigame animation. The GDD defines the full player behavior and <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#12-design-acceptance-cases">acceptance cases</a>.</p><p>The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-baseline.html#current-implementation-evidence">baseline&#39;s November 11 audit</a> records existing systems and 57 passing Wordle EditMode checks. Those checks do not establish this proposed architecture, new lesson progression, or Android acceptance. Android Build Support was missing at audit; readiness remains unverified after the cancelled installation. After FINAL approval, the first technical handoff should demonstrate an ordered lesson and scene return with save/reload on a named build before widening the content set. Preserve integration, device QA, manuscript work, and rehearsal before the November 21, 2026 pre-final.</p><h2 id="historical-technical-reference">Historical technical reference<a class="header-anchor" href="#historical-technical-reference" aria-label="Link to this section">​</a></h2><p>Everything below preserves the October 12 source and October 23 V2 planning for provenance. Its economy requirements, old component status, task IDs, dates, and delivery instructions are historical and do not override the current GDD or development gate above.</p><p>Adopted October 12, 2026 from <a href="/Chainy-Docs/content/docs/archive/source-material/technical-design-christian-2026-10-12.html">Christian Jude Villaber&#39;s supplied design</a>. The user identifies it as written and verified by the Tech Lead. This reference summarizes that design; open inconsistencies are listed explicitly.</p><h3 id="v2-integration-addendum--october-23-2026">V2 integration addendum — October 23, 2026<a class="header-anchor" href="#v2-integration-addendum--october-23-2026" aria-label="Link to this section">​</a></h3><p><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/game-design.html">GDD v2</a> now governs gameplay. The following October 12 component reference remains useful infrastructure, not a requirement to finish three standalone mini-games before beta.</p><p>The November 10 core needs quest/prerequisite state, wallet/inventory/ledger transactions, restoration flags, journal/encyclopedia progress and checkpoint saves. Reuse existing components and define only the interfaces actually needed. Route UI actions through View → Handler → Service; use typed events for notifications and ServiceRegistry for shared providers, consistent with the Unity project&#39;s AGENTS.md. The older source&#39;s blanket event-command wording is not permission to bypass those conventions.</p><p>Christian must map this behavior to the actual code and SQLite schema before implementation. Do not manufacture new managers or assume the old five-entity model covers these states. Purchase/reward operations require atomic related updates and repeat-safe commands; failed saves must not leave a balance/ownership/quest mismatch. Blockchain repair consumes the same saved fictional purchase and is distinct from BlockMatch.</p><p>A01–A03 is conditional stretch with an actual local classifier. Teacher provisioning/collection and standalone Wordle/BlockMatch remain later work. The reference below records original responsibilities and source discrepancies; v2 delivery boundaries supersede its old rollout order.</p><h3 id="how-the-game-is-organized">How the game is organized<a class="header-anchor" href="#how-the-game-is-organized" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Layer</th><th>Plain-language purpose</th><th>Components</th></tr></thead><tbody><tr><td>Presentation</td><td>Show the game and capture player actions</td><td>UI, input devices, UI Manager</td></tr><tr><td>Game logic</td><td>Decide what an action means and run the current activity</td><td>Input Manager, Game Manager, Quiz/Wordle/BlockMatch Managers, Level Manager, SceneLoader, Progress Manager</td></tr><tr><td>Data</td><td>Save and retrieve local records</td><td>Database Manager, SQLite</td></tr></tbody></table><p>The Event Bus carries commands and notifications between components. The Service Locator supplies registered services. UI Manager listens to events and is explicitly excluded from Service Locator registration. Game Manager activates only one mini-game at a time.</p><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  P[Player touch or controls] --&gt; I[Input Manager]
  I --&gt; E[Event Bus]
  E --&gt; G[Game Manager]
  G --&gt; L[Level Manager and SceneLoader]
  G --&gt; M[Active Quiz, Wordle or BlockMatch]
  M --&gt; E
  E --&gt; U[UI Manager]
  U --&gt; V[Screens and feedback]
  E --&gt; R[Progress Manager]
  L --&gt; R
  R --&gt; D[Database Manager]
  D --&gt; DB[(Local SQLite)]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>This is a simplified responsibility diagram. The source&#39;s <a href="/Chainy-Docs/attachments/docs/media/technical-design/image1.png">full diagram</a> also includes Dialogue Manager and object pooling.</p><h3 id="component-responsibilities">Component responsibilities<a class="header-anchor" href="#component-responsibilities" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Component</th><th>Owns</th><th>Important boundary</th></tr></thead><tbody><tr><td>Input Manager</td><td>Convert raw touch/pointer/keyboard input into game commands</td><td>Ignore input that is invalid during load, pause, save or board resolution</td></tr><tr><td>Event Bus</td><td>Route commands and notifications</td><td>Subscribers must not remain active after their scene/session ends</td></tr><tr><td>Game Manager</td><td>App state, session lifecycle, start/pause/resume/exit, active mini-game</td><td>Route gameplay to one mode only</td></tr><tr><td>UI Manager</td><td>Screens, HUD and feedback from events</td><td>No SQL; not registered in Service Locator</td></tr><tr><td>Level Manager</td><td>Level content, difficulty, objectives and configuration</td><td>Data comes through Progress Manager in the source architecture</td></tr><tr><td>SceneLoader</td><td>Load/unload scenes and report success/failure</td><td>Game Manager waits for readiness before starting play</td></tr><tr><td>Quiz Manager</td><td>Questions, answer evaluation and scoring</td><td>Return a result for persistence</td></tr><tr><td>Wordle Manager</td><td>Guess validation, letter evaluation and outcome</td><td>Follow the agreed dictionary and repeated-letter rules</td></tr><tr><td>BlockMatch Manager</td><td>Board moves, matches, cascades and objectives</td><td>Finish board resolution before accepting another move</td></tr><tr><td>Object Pooling</td><td>Reuse objects and effects</td><td>Reset objects when returned/reused</td></tr><tr><td>Progress Manager</td><td>Progress, unlocks, checkpoints and read/write coordination</td><td>Request storage operations and report their outcome</td></tr><tr><td>Database Manager</td><td>Parameterized SQL, transactions and schema changes</td><td>Central storage access; returns data or an explicit error</td></tr><tr><td>SQLite</td><td>Local content and learner records</td><td>No automatic cloud synchronization</td></tr><tr><td>Service Locator</td><td>Register and resolve service dependencies</td><td>Validate required services during startup</td></tr><tr><td>Dialogue Manager</td><td>Learning dialogue/interactions shown in the source diagram</td><td>Exact responsibility/API is absent from Part II; Christian must reconcile it</td></tr></tbody></table><p>Do not create replacement manager frameworks to match the old generated design. Work with the actual project structure and the Tech Lead&#39;s existing scripts.</p><h3 id="load-and-save-flows">Load and save flows<a class="header-anchor" href="#load-and-save-flows" aria-label="Link to this section">​</a></h3><p><strong>Load:</strong> profile input → Progress Manager → Database Manager → SQLite → Progress Manager → interested systems and UI. Activate the selected learner only after the read succeeds. A missing profile and a database error must lead to different messages.</p><p><strong>Save:</strong> active mini-game produces a result → Game Manager handles session state → Progress Manager requests a save → Database Manager writes it → Progress Manager reports success/failure → UI shows the outcome.</p><p>Recommended reliability rule: save related result/progress changes together; a retry must not count the same completion twice. The exact identifier and transaction are Christian&#39;s CH-04 decision. A save failure must leave the last successful save available.</p><p><strong>Return or switch learner:</strong> finish or resolve the current pending save, stop the active mode and clear its UI/state before loading the next profile. <strong>Pause/relaunch:</strong> resume a supported saved point; do not promise exact mid-animation or mid-cascade restoration. See the <a href="/Chainy-Docs/content/docs/design/app-flow.html">flow reference</a>.</p><h3 id="source-reconciliation-required">Source reconciliation required<a class="header-anchor" href="#source-reconciliation-required" aria-label="Link to this section">​</a></h3><p>These are small corrections for Christian, not grounds for discarding his architecture.</p><table><thead><tr><th>Source mismatch</th><th>Proposed resolution</th><th>Task</th></tr></thead><tbody><tr><td>Part IV adds Score Manager; Part II assigns scoring to Quiz Manager</td><td>Keep scoring in the active mode unless Christian confirms an existing shared Score Manager and its interface</td><td>CH-02/04</td></tr><tr><td>Part IV says Progress Manager generates SQL and one load step goes directly to the database; Parts I–II give SQL to Database Manager</td><td>Use Progress Manager for requests and Database Manager for SQL, following Parts I–II</td><td>CH-04</td></tr><tr><td>Dialogue Manager appears in the diagram and milestones but not the responsibility table</td><td>Record the existing dialogue component and how it starts/finishes an activity</td><td>CH-05</td></tr><tr><td>Architecture says content is in SQLite; current quiz reads ScriptableObjects</td><td>Document whether ScriptableObjects seed SQLite or remain the authoritative packaged quiz source; avoid two editable copies</td><td>CH-04/06</td></tr><tr><td>Sessions/checkpoints are promised but absent from the five-entity dictionary</td><td>Obtain the actual schema and define the smallest fields needed for supported resume and evaluation</td><td>CH-04</td></tr><tr><td>Source names Unity Cloud, while repository documents link Chainy-Game</td><td>Confirm the build source and revision; do not duplicate or migrate source by assumption</td><td>CH-03</td></tr></tbody></table><h3 id="data-and-implementation-status">Data and implementation status<a class="header-anchor" href="#data-and-implementation-status" aria-label="Link to this section">​</a></h3><p>The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/database-schema.html">database reference</a> adopts User, Module, Lesson, User_Progress and User_Analytics as the source model. It preserves uncertain field names and data meanings as questions. No new runnable schema or migration is implied.</p><p>Part VI reports SQLite, profile, Quiz, UI and models in progress; player movement completed; Wordle and BlockMatch not started. The evidence named is summarized in the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-baseline.html#current-implementation-evidence">baseline</a>. Source file names are reported evidence, not files inspected in this repository.</p><h3 id="existing-project-locations">Existing project locations<a class="header-anchor" href="#existing-project-locations" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Area</th><th>Location reported in source</th></tr></thead><tbody><tr><td>Scripts</td><td>Assets/Scripts/</td></tr><tr><td>Player controller</td><td>Assets/Scripts/Feature/PlayerSystem</td></tr><tr><td>Dialogue plugin</td><td>Assets/Plugins/</td></tr><tr><td>UI</td><td>Assets/UI</td></tr><tr><td>Scenes</td><td>Assets/Scenes</td></tr><tr><td>SceneLoader</td><td>Assets/Scripts/Core/SceneloaderSystem</td></tr><tr><td>Database</td><td>Assets/Scripts/Feature/Database System</td></tr></tbody></table><p>The folder screenshot shows “Features” while the table uses “Feature.” Preserve the actual paths in the game project; Christian should confirm spelling before task handoff. Do not reorganize working source solely to match a document.</p><h3 id="next-technical-handoff">Next technical handoff<a class="header-anchor" href="#next-technical-handoff" aria-label="Link to this section">​</a></h3><p>Christian supplies the actual schema, build source/revision and a working W01–W04 → save → reload demonstration, followed by B01–B03/demo B07. Miguel checks UI/profile separation and failed-save feedback; Sean records approved result meanings. Wordle/BlockMatch are not prerequisites for this handoff.</p><p><strong>Beta: November 10 — Cryptita Plays community beta testing. Pre-final: November 21, 2026.</strong> Detailed scheduling is in the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/kanban-plan-draft.html">task plan</a>.</p></div>`,1)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
